import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    vmax = max(a)

    phi = list(range(vmax + 1))
    for p in range(2, vmax + 1):
        if phi[p] == p:
            for x in range(p, vmax + 1, p):
                phi[x] -= phi[x] // p

    divisors = [[] for _ in range(vmax + 1)]
    for d in range(1, vmax + 1):
        for x in range(d, vmax + 1, d):
            divisors[x].append(d)

    # weighted[d] = sum of 2^(i-1) over earlier positions i with d | A_i
    weighted = [0] * (vmax + 1)
    answer = 0
    power = 1
    out = []

    for x in a:
        contribution = 0
        for d in divisors[x]:
            contribution += phi[d] * weighted[d]
        answer = (2 * answer + contribution) % MOD
        out.append(str(answer))
        for d in divisors[x]:
            weighted[d] = (weighted[d] + power) % MOD
        power = power * 2 % MOD

    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

