import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    vals = data[1:]
    m = max(vals, default=1)
    spf = list(range(m + 1))
    for p in range(2, int(m ** 0.5) + 1):
        if spf[p] == p:
            for x in range(p * p, m + 1, p):
                if spf[x] == x:
                    spf[x] = p
    nim = 0
    for x in vals:
        count = 0
        while x > 1:
            x //= spf[x]
            count += 1
        nim ^= count
    print('Anna' if nim else 'Bruno')

