from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ending=[[] for _ in range(n+1)]
        for i,(a,b) in enumerate(conflictingPairs):
            if a>b: a,b=b,a
            ending[b].append((a,i))
        top=second=0
        count=0
        top_id=-1
        gain=[0]*len(conflictingPairs)
        total=0
        for r in range(1,n+1):
            for x,i in ending[r]:
                if x>top:
                    second=top
                    top=x; count=1; top_id=i
                elif x==top:
                    count+=1
                elif x>second:
                    second=x
            total += r-top
