from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ending = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ending[b].append((a, i))

        largest = second = 0
        largest_count = 0
        largest_id = -1
        gains = [0] * m
        total = 0

        for right in range(1, n + 1):
            for left, pair_id in ending[right]:
                if left > largest:
                    second = largest
                    largest = left
                    largest_count = 1
                    largest_id = pair_id
                elif left == largest:
                    largest_count += 1
                elif left > second:
                    second = left

            total += right - largest
            if largest_count == 1:
                gains[largest_id] += largest - second

        return total + max(gains)

