import sys
import math


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, budget = data[0], data[1]
    processes = []
    pos = 2
    for _ in range(n):
        a, p, b, q = data[pos:pos + 4]
        pos += 4
        period = b // math.gcd(a, b)
        processes.append((a, p, b, q, period))

    def minimum_cost(w, a, p, b, q, period):
        if w == 0:
            return 0

        # Buying only S machines is also a candidate.
        best = ((w + a - 1) // a) * p

        # For each residue of the number of S machines modulo period,
        # the cost is linear as that count increases by period. Thus only
        # the two endpoints of each residue class need to be considered.
        max_s = (w - 1) // a
        for r in range(min(period - 1, max_s) + 1):
            last = r + ((max_s - r) // period) * period
            for count_s in (r, last):
                count_t = (w - a * count_s + b - 1) // b
                cost = p * count_s + q * count_t
                if cost < best:
                    best = cost
        return best

    def feasible(w):
        total = 0
        for a, p, b, q, period in processes:
            total += minimum_cost(w, a, p, b, q, period)
            if total > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(low)


if __name__ == '__main__':
    main()

