class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        n = len(s)

        # Pascal triangle: comb[a][b] = number of ways to choose b positions
        # among a positions.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for a in range(1, n + 1):
            comb[a][0] = comb[a][a] = 1
            for b in range(1, a):
                comb[a][b] = (comb[a - 1][b - 1] + comb[a - 1][b]) % mod

        # Count values smaller than s by their number of set bits.
        by_weight = [0] * (n + 1)
        ones_so_far = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for extra_ones in range(remaining + 1):
                    weight = ones_so_far + extra_ones
                    by_weight[weight] = (by_weight[weight] + comb[remaining][extra_ones]) % mod
                ones_so_far += 1

        answer = 0
        for weight in range(1, n + 1):
            # For a number with this weight, one operation produces weight;
            # then repeatedly apply popcount until reaching 1.
            value = weight
            steps = 0
            while value > 1:
                value = value.bit_count()
                steps += 1
            if steps + 1 <= k:
                answer = (answer + by_weight[weight]) % mod

        return answer

