import sys
from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n, m, q = next(it), next(it), next(it)
    people = [(next(it), next(it)) for _ in range(m)]
    queries = [(next(it), next(it)) for _ in range(q)]

    # Segment tree nodes represent ranges of towns. Directed edges from a
    # range node to its children allow constraints to cover a whole interval.
    size = 1
    while size < n:
        size <<= 1
    seg_count = 2 * size

    output = []
    for left, right in queries:
        parent = list(range(n + 1))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        for idx in range(left - 1, right):
            s, t = people[idx]
            a, b = find(s), find(t)
            if a != b:
                parent[a] = b

        # Compress towns to their equality-component representatives.
        rep = [0] * (n + 1)
        for town in range(1, n + 1):
            rep[town] = find(town)

        total = seg_count + n + 1
        graph = [[] for _ in range(total)]
        indeg = [0] * total

        def add_edge(u, v):
            graph[u].append(v)
            indeg[v] += 1

        # Segment tree edges point down to the represented towns.
        for node in range(1, size):
            add_edge(node, node * 2)
            add_edge(node, node * 2 + 1)
        for town in range(1, n + 1):
            add_edge(size + town - 1, seg_count + rep[town])

        def add_range(src, lo, hi, forward):
            # Inclusive town range [lo, hi]. Add src->range nodes when
            # forward=True, otherwise range nodes->src.
            l, r = lo - 1 + size, hi + size
            while l < r:
                if l & 1:
                    if forward:
                        add_edge(src, l)
                    else:
                        add_edge(l, src)
                    l += 1
                if r & 1:
                    r -= 1
                    if forward:
                        add_edge(src, r)
                    else:
                        add_edge(r, src)
                l >>= 1
                r >>= 1

        for idx in range(left - 1, right):
            s, t = people[idx]
            lo, hi = min(s, t) + 1, max(s, t) - 1
            endpoint = seg_count + rep[s]
            if s < t:
                add_range(endpoint, lo, hi, True)
            else:
                add_range(endpoint, lo, hi, False)

        # A directed cycle means the strict inequalities are inconsistent.
        queue = deque(i for i in range(total) if indeg[i] == 0)
        seen = 0
        while queue:
            u = queue.popleft()
            seen += 1
            for v in graph[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    queue.append(v)

        output.append("Yes" if seen == total else "No")

    sys.stdout.write("\n".join(output))

