class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(-1, 1), (1, 1), (1, -1), (-1, -1)]
        size = n * m * 4
        straight = array('H', [0]) * size
        turned = array('H', [0]) * size

        def row_order(d):
            return range(n - 1, -1, -1) if dirs[d][0] > 0 else range(n)

        # Longest valid alternating ray beginning at each cell and direction.
        for d, (dr, dc) in enumerate(dirs):
            cols = range(m - 1, -1, -1) if dc > 0 else range(m)
            for r in row_order(d):
                for c in cols:
                    v = grid[r][c]
                    if v == 1:
                        continue
                    nr, nc = r + dr, c + dc
                    length = 1
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2 - v:
                        length += straight[(nr * m + nc) * 4 + d]
                    straight[(r * m + c) * 4 + d] = length

        # Longest sequence from each cell/direction with at most one clockwise turn.
        for d, (dr, dc) in enumerate(dirs):
            clockwise = (d + 1) % 4
            tr, tc = dirs[clockwise]
            cols = range(m - 1, -1, -1) if dc > 0 else range(m)
            for r in row_order(d):
                for c in cols:
                    v = grid[r][c]
                    if v == 1:
                        continue
                    length = 1
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2 - v:
                        length = max(length, 1 + turned[(nr * m + nc) * 4 + d])
                    nr, nc = r + tr, c + tc
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2 - v:
                        length = max(length, 1 + straight[(nr * m + nc) * 4 + clockwise])
                    turned[(r * m + c) * 4 + d] = length

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    answer = max(answer, 1)
                    for d, (dr, dc) in enumerate(dirs):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2:
                            answer = max(answer, 1 + turned[(nr * m + nc) * 4 + d])
        return answer

