from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        # Factorials larger than k need not be represented exactly.
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(k, fact[i - 1] * i)

        odds = (n + 1) // 2
        evens = n // 2
        remaining = set(range(1, n + 1))
        answer = []
        previous_parity = None

        for pos in range(n):
            length = n - pos - 1
            found = False
            for value in sorted(remaining):
                parity = value & 1
                if previous_parity is not None and parity == previous_parity:
                    continue

                left_odds = odds - (parity == 1)
                left_evens = evens - (parity == 0)
                next_parity = 1 - parity
                needed_odds = (length + (next_parity == 1)) // 2
                needed_evens = length - needed_odds

                if left_odds == needed_odds and left_evens == needed_evens:
                    block = fact[left_odds] * fact[left_evens]
                else:
                    block = 0

                if k > block:
                    k -= block
                else:
                    answer.append(value)
                    remaining.remove(value)
                    if parity == 1:
                        odds -= 1
                    else:
                        evens -= 1
                    previous_parity = parity
                    found = True
                    break

            if not found:
                return []

        return answer

