class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        coeff = []
        for i in range(m):
            c = pow(10, n - 1 - i, k)
            if i != n - 1 - i:
                c = (c + pow(10, i, k)) % k
            coeff.append(c)

        full = (1 << k) - 1
        # dp[i] marks all residues achievable by positions i and later.
        dp = [0] * (m + 1)
        dp[m] = 1  # The empty suffix contributes residue zero.
        for i in range(m - 1, -1, -1):
            mask = 0
            nxt = dp[i + 1]
            c = coeff[i]
            for digit in range(10):
                shift = (digit * c) % k
                mask |= ((nxt << shift) | (nxt >> (k - shift))) & full
            dp[i] = mask

        chosen = []
        remainder = 0
        for i, c in enumerate(coeff):
            for digit in range(9, -1, -1):
                if i == 0 and digit == 0:
                    continue
                needed = (-(remainder + digit * c)) % k
                if (dp[i + 1] >> needed) & 1:
                    chosen.append(str(digit))
                    remainder = (remainder + digit * c) % k
                    break

        half = ''.join(chosen)
        return half + (half[:-1][::-1] if n % 2 else half[::-1])

