class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        parent[0] = 0
        order = [0]
        for u in order:
            for v, w in graph[u]:
                if v == parent[u]:
                    continue
                parent[v] = u
                order.append(v)

        # dp0[u]: best subtree value when u's parent edge is absent.
        # dp1[u]: best subtree value when u's parent edge is present.
        dp0 = [0] * n
        dp1 = [0] * n
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += dp0[v]
                    gains.append(w + dp1[v] - dp0[v])
            gains.sort(reverse=True)

            total0 = base
            total1 = base
            for i, gain in enumerate(gains):
                if gain <= 0:
                    break
                if i < k:
                    total0 += gain
                if i < k - 1:
                    total1 += gain
            dp0[u] = total0
            dp1[u] = total1

        return dp0[0]

