import sys
from functools import lru_cache

sys.setrecursionlimit(10000)


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n_a, n_b, n_c = data[:3]
    values = data[3:]
    n = n_a + n_b + n_c
    all_cards = (1 << n) - 1

    smaller = [0] * n
    for i, x in enumerate(values):
        mask = 0
        for j, y in enumerate(values):
            if y < x:
                mask |= 1 << j
        smaller[i] = mask

    @lru_cache(None)
    def winning(a_hand, b_hand, turn):
        hand = a_hand if turn == 0 else b_hand
        if hand == 0:
            return False

        other = b_hand if turn == 0 else a_hand
        for i in range(n):
            bit = 1 << i
            if not (hand & bit):
                continue

            remaining = hand ^ bit
            # After playing this card, the table consists of every card
            # not in either player's remaining hand.
            table = all_cards ^ (remaining | other)
            captures = table & smaller[i]

            if turn == 0:
                if not winning(remaining, b_hand, 1):
                    return True
            else:
                if not winning(a_hand, remaining, 0):
                    return True

            while captures:
                captured = captures & -captures
                captures -= captured
                if turn == 0:
                    if not winning(remaining | captured, b_hand, 1):
                        return True
                else:
                    if not winning(a_hand, remaining | captured, 0):
                        return True
        return False

    a_hand = (1 << n_a) - 1
    b_hand = ((1 << n_b) - 1) << n_a
    print('Takahashi' if winning(a_hand, b_hand, 0) else 'Aoki')


