    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    pos = 1
    out = []

    for _ in range(t):
        h = int(data[pos]); w = int(data[pos + 1]); pos += 2
        grid = data[pos:pos + h]; pos += h

        n = h + w
        parent = list(range(n))
        rank = [0] * n
        xr = [0] * n  # value(node) xor value(parent(node))

        def find(x):
            if parent[x] != x:
                old = parent[x]
                parent[x] = find(old)
                xr[x] ^= xr[old]
            return parent[x]

        def union(a, b, v):
            ra = find(a); rb = find(b)
            xa = xr[a]; xb = xr[b]
            if ra == rb:
                return (xa ^ xb) == v
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
                xa, xb = xb, xa
            parent[rb] = ra
            xr[rb] = xa ^ xb ^ v
            if rank[ra] == rank[rb]:
                rank[ra] += 1
            return True

        col_prefix = [0] * w
        ok = True
        for i, row in enumerate(grid):
            row_prefix = 0
            for j, ch in enumerate(row):
                if ch == 66:
                    if not union(i, h + j, 1 ^ row_prefix ^ col_prefix[j]):
                        ok = False
                is_a = (ch == 65)
                row_prefix ^= is_a
                col_prefix[j] ^= is_a
            if row_prefix:
                ok = False
        if any(col_prefix):
            ok = False

        if not ok:
            out.append('0')
        else:
            components = sum(find(i) == i for i in range(n))
            out.append(str(pow(2, components, MOD)))

    sys.stdout.write('\n'.join(out))

