class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(part):
            if not part:
                return range(n + 1)
            positions = []
            pos = s.find(part)
            while pos != -1:
                positions.append(pos)
                pos = s.find(part, pos + 1)
            return positions

        starts_a = occurrences(a)
        starts_b = occurrences(b)
        starts_c = occurrences(c)
        len_a, len_b, len_c = len(a), len(b), len(c)
        best = n + 1

        for start in starts_a:
            b_index = bisect_left(starts_b, start + len_a)
            if b_index == len(starts_b):
