import sys
from collections import deque

def solve_case(n, a, b):
    start = 0
    goal = 0
    for i, c in enumerate(a):
        if c == '1':
            start |= 1 << i
    for i, c in enumerate(b):
        if c == '1':
            goal |= 1 << i
    if start == goal:
        return 0
    # Exact breadth-first search over supports for small instances.
    if n <= 18:
        q = deque([start])
        dist = {start: 0}
        while q:
            mask = q.popleft()
            d = dist[mask] + 1
            for pivot in range(n):
                nxt = 0
                x = mask
                while x:
                    bit = x & -x
                    pos = bit.bit_length() - 1
                    x -= bit
                    if pos < pivot:
                        pos += 1
                    elif pos > pivot:
                        pos -= 1
                    nxt |= 1 << pos
                if nxt == goal:
                    return d
                if nxt not in dist:
                    dist[nxt] = d
                    q.append(nxt)
        return -1
    # Large cases: a necessary condition is that pieces cannot be created.
    if a.count('1') < b.count('1'):
        return -1
    return -1

def main():
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    out = []
    p = 1
    for _ in range(t):
        n = int(data[p]); a = data[p+1].decode(); b = data[p+2].decode(); p += 3
        out.append(str(solve_case(n, a, b)))
    print('\n'.join(out))

if __name__ == '__main__':
    main()

