class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        dp = [1] * n  # Bit s is set if sum s is achievable at this index.
        masks = [(1 << (x + 1)) - 1 for x in nums]
        missing = sum(x != 0 for x in nums)

        if missing == 0:
            return 0

        for k, (l, r, val) in enumerate(queries, 1):
            for i in range(l, r + 1):
                old = dp[i]
                new = (old | (old << val)) & masks[i]
                if new != old:
                    dp[i] = new
                    if not ((old >> nums[i]) & 1) and ((new >> nums[i]) & 1):
                        missing -= 1
            if missing == 0:
                return k

        return -1

