class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        limit = max(n, m, 10**len(str(n)) - 1)
        is_prime = [True] * (limit + 1)
        if limit >= 0:
            is_prime[0] = False
        if limit >= 1:
            is_prime[1] = False
        p = 2
        while p * p <= limit:
            if is_prime[p]:
                for multiple in range(p * p, limit + 1, p):
                    is_prime[multiple] = False
            p += 1
        if is_prime[n] or is_prime[m]:
            return -1

        dist = {n: n}
        heap = [(n, n)]
        while heap:
            cost, x = heapq.heappop(heap)
            if dist.get(x) != cost:
                continue
            if x == m:
                return cost

            place = 1
            while place <= x or place == 1:
                digit = (x // place) % 10
                if digit > 0:
                    y = x - place
                    if not is_prime[y]:
                        new_cost = cost + y
                        if new_cost < dist.get(y, float('inf')):
                            dist[y] = new_cost
                            heapq.heappush(heap, (new_cost, y))
                if digit < 9:
                    y = x + place
                    if y <= limit and not is_prime[y]:
                        new_cost = cost + y
                        if new_cost < dist.get(y, float('inf')):
                            dist[y] = new_cost
                            heapq.heappush(heap, (new_cost, y))
                place *= 10
        return -1

