from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # Prefix polynomial hashes modulo 2**64.
        mask = (1 << 64) - 1
        base = 911382323
        power = [1] * (n + 1)
        prefix = [0] * (n + 1)
        for k, value in enumerate(nums):
            power[k + 1] = (power[k] * base) & mask
            prefix[k + 1] = (prefix[k] * base + value + 1) & mask

        def equal(a: int, b: int, length: int) -> bool:
            ha = (prefix[a + length] - prefix[a] * power[length]) & mask
            hb = (prefix[b + length] - prefix[b] * power[length]) & mask
            return ha == hb

        answer = 0
        for first_end in range(1, n - 1):
            # Count splits satisfying nums1 being a prefix of nums2.
            first_condition = (
                2 * first_end <= n - 1 and equal(0, first_end, first_end)
            )
            if first_condition:
                answer += n - max(first_end + 1, 2 * first_end)

            # Check the other condition for each possible length of nums2.
            max_length = (n - first_end) // 2
            for length in range(1, max_length + 1):
                if equal(first_end, first_end + length, length):
                    answer += 1
                    # Avoid counting a split satisfying both conditions twice.
                    if first_condition and length >= first_end:
                        answer -= 1

        return answer

