import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    s = data[1].decode()
    t = data[2].decode()
    n, m = len(s), len(t)

    if s == t:
        print("Yes")
        return
    if abs(n - m) > 1:
        print("No")
        return
    if n == m:
        mismatches = 0
        for a, b in zip(s, t):
            if a != b:
                mismatches += 1
                if mismatches > 1:
                    break
        print("Yes" if mismatches <= 1 else "No")
        return

    if n > m:
        s, t = t, s
    i = j = 0
    skipped = False
    while i < len(s) and j < len(t):
        if s[i] == t[j]:
            i += 1
            j += 1
        elif skipped:
            print("No")
            return
        else:
            skipped = True
            j += 1
    print("Yes")

