class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)
        target = [False] * n
        for i in targetIndices:
            target[i] = True

        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            # Descending order ensures this character cannot be used twice.
            for j in range(m, -1, -1):
                if j < m and ch == pattern[j] and dp[j] > dp[j + 1]:
                    dp[j + 1] = dp[j]
                if target[i] and dp[j] != neg:
                    dp[j] += 1

        return dp[m]

